        if(route=="set-editor"&&c.Request.HttpMethod=="POST") { string body;using(var reader=new StreamReader(c.Request.InputStream,Encoding.UTF8))body=reader.ReadToEnd();var data=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(body);string editor=Convert.ToString(data["editor"]);bool remember=Convert.ToBoolean(data["remember"]);lock(gate){if(remember&&(!editors.ContainsKey(editor)||!File.Exists(editor))){c.Response.StatusCode=404;Reply(c,Encoding.UTF8.GetBytes("{\"code\":\"editor_missing\"}"),"application/json; charset=utf-8");return;}if(data.ContainsKey("tabs"))showTabs=Convert.ToBoolean(data["tabs"]);if(data.ContainsKey("indexSearch"))searchIndex=Convert.ToBoolean(data["indexSearch"]);if(data.ContainsKey("dark"))darkTheme=Convert.ToBoolean(data["dark"]);if(data.ContainsKey("language")){string json,name,candidate=Convert.ToString(data["language"]);if(!TryLocale(candidate,out json,out name)){c.Response.StatusCode=400;c.Response.Close();return;}uiLanguage=candidate;}string chosen=remember?editor:null;var changes=new Dictionary<string,object>{{"editor",chosen}};if(data.ContainsKey("tabs"))changes["tabs"]=showTabs;if(data.ContainsKey("indexSearch"))changes["indexSearch"]=searchIndex;if(data.ContainsKey("dark"))changes["dark"]=darkTheme;if(data.ContainsKey("language"))changes["language"]=uiLanguage;SaveSettings(changes);pinnedEditor=chosen;}Reply(c,Encoding.UTF8.GetBytes("{}"),"application/json; charset=utf-8");return;}

        if(route=="open" && c.Request.HttpMethod=="POST") { string chosen=null; var dialogThread=new Thread(()=>{using(var dialog=new OpenFileDialog()){dialog.Title=NativeText("native_open_title","Open document");dialog.Filter=NativeText("native_file_filter","Markdown and text files")+"|*.md;*.markdown;*.mdown;*.txt";dialog.CheckFileExists=true;if((owner==IntPtr.Zero?dialog.ShowDialog():dialog.ShowDialog(new DialogOwner(owner)))==DialogResult.OK)chosen=dialog.FileName;}});dialogThread.SetApartmentState(ApartmentState.STA);dialogThread.Start();dialogThread.Join();if(chosen==null){c.Response.StatusCode=204;c.Response.Close();return;}lock(gate){folder=Path.GetDirectoryName(chosen);initial=Path.GetFileName(chosen);paths.Clear();entries.Clear();directories.Clear();Scan(folder);}route="manifest"; }
        if(route=="open-folder" && c.Request.HttpMethod=="POST") { string chosen=null;var t=new Thread(()=>{using(var dialog=new FolderBrowserDialog()){dialog.Description="찾아볼 폴더 선택";if((owner==IntPtr.Zero?dialog.ShowDialog():dialog.ShowDialog(new DialogOwner(owner)))==DialogResult.OK)chosen=dialog.SelectedPath;}});t.SetApartmentState(ApartmentState.STA);t.Start();t.Join();if(chosen==null){c.Response.StatusCode=204;c.Response.Close();return;}lock(gate){folder=chosen;initial="";paths.Clear();entries.Clear();directories.Clear();Scan(folder);}route="manifest"; }
        if(route=="open-tab" && c.Request.HttpMethod=="POST") { string selected;using(var reader=new StreamReader(c.Request.InputStream,Encoding.UTF8))selected=reader.ReadToEnd();lock(gate){selected=Path.GetFullPath(selected.Replace('/','\\'));if(!openedDocuments.Contains(selected)||!File.Exists(selected)){c.Response.StatusCode=404;c.Response.Close();return;}folder=Path.GetDirectoryName(selected);initial=Path.GetFileName(selected);paths.Clear();entries.Clear();directories.Clear();Scan(folder);}route="manifest"; }
        if(route=="resolve" && c.Request.HttpMethod=="POST") { string body;using(var reader=new StreamReader(c.Request.InputStream,Encoding.UTF8))body=reader.ReadToEnd();var j=new JavaScriptSerializer();var req=j.Deserialize<Dictionary<string,string>>(body);lock(gate){string baseName=req["base"],link=Uri.UnescapeDataString(req["link"].Split('#')[0].Split('?')[0]);if(folder==null||Path.IsPathRooted(link)||link.Contains(":")){c.Response.StatusCode=404;c.Response.Close();return;}string baseFile=Path.GetFullPath(Path.Combine(folder,baseName.Replace('/','\\')));if(!paths.Contains(baseFile)){c.Response.StatusCode=404;c.Response.Close();return;}string target=Path.GetFullPath(Path.Combine(Path.GetDirectoryName(baseFile),link.Replace('/','\\')));string type=Mime(target);if(type==null||!File.Exists(target)||(File.GetAttributes(target)&FileAttributes.ReparsePoint)!=0){c.Response.StatusCode=404;c.Response.Close();return;}int index=paths.IndexOf(target);if(index<0){index=paths.Count;paths.Add(target);}Reply(c,Encoding.UTF8.GetBytes(j.Serialize(new {id=index,type=type.Split(';')[0]})),"application/json; charset=utf-8");return;} }
        if(route=="browse" && c.Request.HttpMethod=="POST") { string name;using(var reader=new StreamReader(c.Request.InputStream,Encoding.UTF8))name=reader.ReadToEnd();lock(gate){if(folder==null||!directories.Contains(name)){c.Response.StatusCode=404;c.Response.Close();return;}string dest=Path.Combine(folder,name);if(!Directory.Exists(dest)||(File.GetAttributes(dest)&FileAttributes.ReparsePoint)!=0){c.Response.StatusCode=404;c.Response.Close();return;}folder=dest;initial="";paths.Clear();entries.Clear();directories.Clear();Scan(folder);}route="manifest"; }
        if(route=="up" && c.Request.HttpMethod=="POST") { lock(gate){var parent=folder==null?null:Directory.GetParent(folder);if(parent!=null){folder=parent.FullName;initial="";paths.Clear();entries.Clear();directories.Clear();Scan(folder);}}route="manifest"; }
        if(route=="keep-document" && c.Request.HttpMethod=="POST") {string selected;using(var reader=new StreamReader(c.Request.InputStream,Encoding.UTF8))selected=reader.ReadToEnd();lock(gate){selected=Path.GetFullPath(selected.Replace('/','\\'));if(!openedDocuments.Contains(selected)||!File.Exists(selected)||Mime(selected)==null){c.Response.StatusCode=404;c.Response.Close();return;}int documentId=paths.FindIndex(x=>String.Equals(x,selected,StringComparison.OrdinalIgnoreCase));if(documentId<0){documentId=paths.Count;paths.Add(selected);}Reply(c,Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(new {id=documentId,type=Mime(selected).Split(';')[0]})),"application/json; charset=utf-8");return;}}
        if(route=="folder-history" && c.Request.HttpMethod=="POST") {string requested;using(var reader=new StreamReader(c.Request.InputStream,Encoding.UTF8))requested=reader.ReadToEnd();lock(gate){if(!visitedFolders.Contains(requested)||!Directory.Exists(requested)||(File.GetAttributes(requested)&FileAttributes.ReparsePoint)!=0){c.Response.StatusCode=404;c.Response.Close();return;}folder=requested;initial="";paths.Clear();entries.Clear();directories.Clear();Scan(folder);}route="manifest";}
        if(route=="manifest") { lock(gate) { if(folder!=null)visitedFolders.Add(folder); var j=new JavaScriptSerializer(); j.MaxJsonLength=int.MaxValue; Reply(c,Encoding.UTF8.GetBytes(j.Serialize(new { root=folder??"", initial=initial??"", files=entries, directories=directories, truncated=false, canUp=folder!=null && Directory.GetParent(folder)!=null })),"application/json; charset=utf-8"); } return; }
        int id; if(route.StartsWith("file/") && int.TryParse(route.Substring(5),out id)) { lock(gate) { if(id>=0 && id<paths.Count) { string file=paths[id];byte[] contents=File.ReadAllBytes(file);if(Mime(file).StartsWith("text/"))openedDocuments.Add(file);Reply(c,contents,Mime(file));return; } } }
        c.Response.StatusCode=404;c.Response.Close();
    } catch { try { c.Response.StatusCode=404;c.Response.Close(); } catch {} } }
    [STAThread] static void Main(string[] args) { try {
        string target=args.Length>0?Path.GetFullPath(args[0]):null;
        if(target!=null && File.Exists(target)) { folder=Path.GetDirectoryName(target); initial=Path.GetFileName(target); }
        else if(target!=null && Directory.Exists(target)) { folder=target; initial=""; }
        else { folder=Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);if(String.IsNullOrEmpty(folder)||!Directory.Exists(folder))folder=null; initial=""; }
        if(folder!=null){folder=Path.GetFullPath(folder); Scan(folder);} EnsureInitialSettings();InitEditors();token=Guid.NewGuid().ToString("N");
        string source=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"index.html"); html=File.ReadAllText(source,Encoding.UTF8);
        string bootstrap=@"<script>function loadManifest(data){files.clear();root=data.root;current='';history=[];for(const f of data.files){const url='file/'+f.id;files.set(f.path,{type:f.type,url:url,text:()=>fetch(url).then r=>r})}document.getElementById('folderName').textContent=root;document.getElementById('up').hidden=!data.canUp;const note=document.getElementById('scanNote');note.hidden=!data.truncated;note.textContent='폴더가 많아 일부만 표시했습니다. 더 가까운 폴더에서 열어 주세요.';drawTree();const first=files.has(data.initial)?data.initial:[...files.keys()].find(p=>/\.(md|markdown|mdown|txt)$/i.test(p));if(first)openFile(first,false);else document.getElementById('main').innerHTML='<div class=""welcome""><h1>문서가 없습니다</h1><p>다른 폴더를 선택해 주세요.</p></div>'}fetch('manifest').then(r=>r.json()).then(loadManifest).catch(()=>{document.getElementById('folderName').textContent='폴더를 읽지 못했습니다'});document.getElementById('up').onclick=async()=>{const b=document.getElementById('up');b.disabled=true;try{const r=await fetch('up',{method:'POST',body:current});if(!r.ok)throw Error();loadManifest(await r.json())}catch(e){alert('상위 폴더를 읽지 못했습니다.')}finally{b.disabled=false}};</script>";
        bootstrap=bootstrap.Replace("fetch(url).then r=>r", "fetch(url).then(r=>{if(!r.ok)throw new Error('파일을 읽을 수 없습니다');return r.text()})");
        bootstrap=bootstrap.Replace("function loadManifest(data)","async function loadManifest(data,newTab=false,fromFolderHistory=false)").Replace("if(first)openFile(first,false);","if(first)await openFile(first,false,'',newTab);");
        bootstrap=bootstrap.Replace("textContent=root;", "textContent=root||'열린 문서 없음';").Replace("else document.getElementById('main').innerHTML=", "else if(data.root) document.getElementById('main').innerHTML=");
        bootstrap=bootstrap.Replace("async function loadManifest(data,newTab=false,fromFolderHistory=false){files.clear();", "async function loadManifest(data,newTab=false,fromFolderHistory=false){desktopMode=true;if(!fromFolderHistory)recordFolder(data.root);maybeStartTutorial();desktopDirectories=data.directories||[];desktopCanUp=data.canUp;files.clear();")
            .Replace("document.getElementById('up').hidden=!data.canUp;", "document.getElementById('up').hidden=true;")
            .Replace("const first=files.has(data.initial)?data.initial:[...files.keys()].find(p=>/\\.(md|markdown|mdown|txt)$/i.test(p));", "const first=files.has(data.initial)?data.initial:null;")
            .Replace("<h1>문서가 없습니다</h1><p>다른 폴더를 선택해 주세요.</p>", "<h1>'+esc(t('browse_heading'))+'</h1><p>'+esc(t('browse_desc'))+'</p>");
        bootstrap=bootstrap.Replace("else if(data.root) document.getElementById('main').innerHTML=", "else if(activeDocument){try{const response=await fetch('keep-document',{method:'POST',body:activeDocument});if(!response.ok)throw Error();const item=await response.json(),path=documentPathFromRoot(root,activeDocument),url='file/'+item.id;files.set(path,{type:item.type,url:url,text:()=>fetch(url).then(r=>{if(!r.ok)throw Error();return r.text()})});const scroll=document.getElementById('main').scrollTop;await openFile(path,false);document.getElementById('main').scrollTop=scroll}catch{current='';document.getElementById('main').innerHTML='<div class=\"welcome error\">'+esc(t('document_missing'))+'</div>'}}else if(data.root) document.getElementById('main').innerHTML=");
        bootstrap=bootstrap.Replace("alert('파일을 열지 못했습니다.')","alert(t('open_error'))").Replace("alert('폴더를 열지 못했습니다.')","alert(t('folder_error'))").Replace("alert('상위 폴더를 읽지 못했습니다.')","alert(t('parent_error'))").Replace("textContent='폴더를 읽지 못했습니다'","textContent=t('folder_error')");
        bootstrap=bootstrap.Replace("</script>","document.getElementById('folderInput').addEventListener('change',()=>{document.getElementById('up').hidden=true;document.getElementById('scanNote').hidden=true});const openButton=document.getElementById('openFile');openButton.hidden=false;document.getElementById('editFile').hidden=false;openButton.onclick=async()=>{openButton.disabled=true;try{const r=await fetch('open',{method:'POST'});if(r.status===204)return;if(!r.ok)throw Error();loadManifest(await r.json())}catch(e){alert('파일을 열지 못했습니다.')}finally{openButton.disabled=false}};</script>");
        bootstrap=bootstrap.Replace("</script>","document.getElementById('folderInput').addEventListener('change',()=>{desktopMode=false;drawTree()});document.getElementById('tree').addEventListener('click',async e=>{const parent=e.target.closest('[data-parent]'),dir=e.target.closest('[data-dir]');if(!parent&&!dir)return;try{const r=await fetch(parent?'up':'browse',{method:'POST',body:dir?dir.dataset.dir:''});if(!r.ok)throw Error();document.getElementById('search').value='';loadManifest(await r.json())}catch(err){alert('폴더를 열지 못했습니다.')}});</script>");
        html=html.Replace("</head>","<link rel=\"icon\" href=\"icon.ico\"></head>").Replace("</body>",bootstrap+"</body>");
        var socket=new TcpListener(IPAddress.Loopback,0);socket.Start();int port=((IPEndPoint)socket.LocalEndpoint).Port;socket.Stop();server=new HttpListener();server.Prefixes.Add("http://127.0.0.1:"+port+"/");server.Start();
        string edge=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),@"Microsoft\Edge\Application\msedge.exe");if(!File.Exists(edge))throw new Exception("Microsoft Edge를 찾을 수 없습니다.");
        string viewerProfile=PrepareViewerProfile();Process.Start(new ProcessStartInfo(edge,"--user-data-dir=\""+viewerProfile+"\" --app=http://127.0.0.1:"+port+"/"+token+"/"){UseShellExecute=false});
        while(DateTime.UtcNow-lastRequest<TimeSpan.FromHours(12)) { var pending=server.BeginGetContext(null,null); while(!pending.AsyncWaitHandle.WaitOne(30000) && DateTime.UtcNow-lastRequest<TimeSpan.FromHours(12)) {} if(DateTime.UtcNow-lastRequest>=TimeSpan.FromHours(12))break; var c=server.EndGetContext(pending); ThreadPool.QueueUserWorkItem(_=>Handle(c)); } server.Close();
    } catch(Exception e) { MessageBox.Show(e.Message,"MD/TXT EasyViewer",MessageBoxButtons.OK,MessageBoxIcon.Error); } }
